/// Request enum for GitHub API.
///
/// Each variant wraps a strongly-typed request struct.
pub enum GitHubRequest {
    /// Get repository metadata including default branch
    GetRepository(GetRepositoryRequest),
    /// Get a Git tree (non-recursive, single level)
    GetGitTree(GetGitTreeRequest),
    /// Get a Git tree recursively (may truncate at 100k entries or 7MB)
    GetGitTreeRecursive(GetGitTreeRecursiveRequest),
    /// Get raw file content from repository
    GetRepositoryContentRaw(GetRepositoryContentRawRequest),
    /// List pull requests with metadata
    ListPullRequests(ListPullRequestsRequest),
    /// List files changed in a pull request
    ListPullRequestFiles(ListPullRequestFilesRequest),
    /// List issues (includes PRs; filter by pull_request field)
    ListIssues(ListIssuesRequest),
    /// Get a single issue by number
    GetIssue(GetIssueRequest),
    /// List comments on an issue
    ListIssueComments(ListIssueCommentsRequest),
    /// List timeline events for an issue
    ListIssueTimeline(ListIssueTimelineRequest),
    /// List repository tags
    ListTags(ListTagsRequest),
    /// List releases (linked to tags via tag_name)
    ListReleases(ListReleasesRequest),
    /// Get tag reference (check object.type: 'commit' vs 'tag')
    GetTagReference(GetTagReferenceRequest),
    /// Get annotated tag object details (message, tagger, verification)
    GetAnnotatedTag(GetAnnotatedTagRequest),
    /// List workflow runs for a repository
    ListWorkflowRuns(ListWorkflowRunsRequest),
    /// List repositories for an organization
    ListOrgRepos(ListOrgReposRequest),
}
